mapper.select:
select t.id, t.user_id as userId, t.vacation_id as vacationId, t.start_time as startTime, t.end_time as endTime, t.leave_reason as leaveReason, t.leave_picture as leavePicture, t.approval_criteria_id as approvalCriteriaId, t.apprpval_status as apprpvalStatus, vs.vacation_status as vacationStatus, ls.schedule_id as scheduleId from leave_info t left join vacation_set vs on t.vacation_id=vs.id left join leave_schedule ls on t.id=ls.leave_id
t.apprpval_status = 1 and vs.vacation_enable=1
and t.user_id = #{queryForm.userId}
and DATE_FORMAT(t.start_time,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenStartDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andStartDate},'%Y-%m-%d')
and vs.vacation_status = #{queryForm.vacationStatus}
order by t.start_time asc

select t.id, t.user_id as userId, t.vacation_id as vacationId, t.start_time as startTime, t.end_time as endTime, t.leave_reason as leaveReason, t.leave_picture as leavePicture, t.approval_criteria_id as approvalCriteriaId, t.apprpval_status as apprpvalStatus from leave_info t left join vacation_set vs on t.vacation_id=vs.id
t.apprpval_status in(0,1) and vs.vacation_enable=1
and t.user_id = #{queryForm.userId}
and vs.vacation_status = #{queryForm.vacationStatus}
order by t.start_time asc

select es.work_date date,es.clinic_id companyId,bs.first_start_time
startTime,IFNULL(bs.second_end_time,bs.first_end_time) endTime ,bs.type emType,bs.`name` emName
from employee_schedule es
LEFT JOIN base_schedule bs on es.schedule_id = bs.id
where es.work_date BETWEEN #{startTime} and #{endTime}

    and es.employee_id = #{userId}
